using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    /// <summary>
    /// A fixed resource that returns the application's configuration data.
    /// Clients discover it via resources/list and read it via resources/read.
    /// </summary>
    [McpServerResource(UriTemplate = "config://app/settings",
                       Name = "App Settings",
                       MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Version = "1.0.0",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>
    /// A resource template with a parameter — lets clients read
    /// per-environment configuration (e.g. config://env/production).
    /// </summary>
    [McpServerResource(UriTemplate = "config://env/{environment}",
                       Name = "Environment Config",
                       MimeType = "application/json")]
    public static string GetEnvironmentConfig(string environment)
    {
        var config = new
        {
            Environment = environment,
            DatabaseHost = environment == "production" ? "db.prod.example.com" : "db.dev.example.com",
            LogLevel = environment == "production" ? "Warning" : "Debug",
            CacheEnabled = environment == "production"
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

